// GERADO por scripts/embed-assets.ts — não edite à mão. Rode `bun run embed`.
export interface EmbeddedAsset { contentType: string; text?: string; binary?: Buffer }
export const assets: Record<string, EmbeddedAsset> = {
  "index.html": { contentType: "text/html; charset=utf-8", text: "<!DOCTYPE html>\r\n<html lang=\"pt-BR\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n<title>Gestor de Tráfego Pago</title>\r\n<style>\r\n:root{--bg:#EBEFED;--surface:#fff;--ink:#16201C;--muted:#647570;--line:#D8DFDC;--btn:#16201C;--btn-ink:#fff;\r\n--good:#0B8A4C;--good-bg:#D9F2E4;--good-seg:#2FBF7A;--ok:#0E76B8;--ok-bg:#D8ECF9;--ok-seg:#3AA6E6;\r\n--warn:#8A5F00;--warn-bg:#F6E8BE;--warn-seg:#E2AE1F;--bad:#B72929;--bad-bg:#F8DADA;--bad-seg:#E5595B;--wait-bg:#E3E9E6;--wait:#5D6D68}\r\n*{box-sizing:border-box}\r\nbody{margin:0;background:var(--bg);color:var(--ink);font:400 14px/1.45 system-ui,\"Segoe UI\",Roboto,Arial,sans-serif;padding:0}\r\n.app{display:grid;grid-template-columns:220px minmax(0,1fr);min-height:100vh}\r\n.side{background:var(--surface);border-right:1px solid var(--line);padding:18px 12px;display:flex;flex-direction:column;gap:2px;position:sticky;top:0;height:100vh}\r\n.brand{font-weight:800;font-size:17px;padding:4px 10px 16px}\r\n.nav{display:flex;flex-direction:column;gap:2px}\r\n.nav a{padding:9px 10px;border-radius:9px;text-decoration:none;color:#3A4843;font-weight:600}\r\n.nav a[aria-current=\"page\"]{background:var(--btn);color:var(--btn-ink)}\r\n.main{padding:26px 28px 56px;min-width:0}\r\n.wrap{max-width:1100px;margin:0 auto}\r\n.ph{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;flex-wrap:wrap;margin-bottom:16px}\r\n.ph h1{margin:0;font-size:28px}\r\n.sub{color:var(--muted);font-size:13px;margin:4px 0 0}\r\n.panel{background:var(--surface);border:1px solid var(--line);border-radius:14px;margin-bottom:16px}\r\n.panel-b{padding:18px}\r\n.fb{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}\r\n.ctl{display:inline-flex;align-items:center;gap:8px;height:38px;padding:0 12px;border:1px solid var(--line);border-radius:9px;background:var(--surface)}\r\n.ctl input,.ctl select{border:0;background:transparent;outline:0}\r\n.ctl.search{min-width:240px}.ctl.search input{flex:1}\r\n.btn{display:inline-flex;align-items:center;gap:8px;height:38px;padding:0 14px;border-radius:9px;border:1px solid var(--btn);background:var(--btn);color:var(--btn-ink);font-weight:700;cursor:pointer;text-decoration:none}\r\n.btn.ghost{background:transparent;color:var(--ink);border-color:var(--line)}\r\n.btn:disabled{opacity:.4;cursor:not-allowed}\r\n.in{height:40px;width:100%;padding:0 12px;border:1px solid var(--line);border-radius:9px;background:var(--surface)}\r\ntextarea.in{height:auto;min-height:80px;padding:10px 12px;resize:vertical}\r\n.in.err{border-color:var(--bad)}\r\n.fld{display:grid;gap:6px;margin-bottom:14px}.fld>label{font-weight:700}\r\n.hint{font-size:12.5px;color:var(--muted)}\r\n.err-msg{font-size:13px;color:var(--bad);font-weight:700}\r\n.seg{display:inline-flex;border:1px solid var(--line);border-radius:9px;padding:3px;background:#F4F7F6;gap:2px}\r\n.seg button{height:32px;padding:0 14px;border:0;border-radius:7px;background:transparent;cursor:pointer;font-weight:600}\r\n.seg button[aria-pressed=\"true\"]{background:var(--surface);box-shadow:0 0 0 1px var(--line)}\r\n.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}\r\n.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:6px}\r\n.tbl{width:100%;border-collapse:collapse}\r\n.tbl th{font-size:12px;color:var(--muted);text-align:left;padding:10px 12px;border-bottom:1px solid var(--line);white-space:nowrap}\r\n.tbl td{padding:11px 12px;border-bottom:1px solid #E8EDEB;vertical-align:middle}\r\n.tbl tr.click{cursor:pointer}.tbl tr.click:hover td{background:#F4F7F6}\r\n.tbl td.num,.tbl th.num{text-align:right}\r\n.nm{font-weight:700}\r\n.chip{display:inline-flex;align-items:center;height:24px;padding:0 10px;border-radius:99px;font-size:12px;font-weight:800;white-space:nowrap}\r\n.chip.good{background:var(--good-bg);color:var(--good)}.chip.ok{background:var(--ok-bg);color:var(--ok)}\r\n.chip.warn{background:var(--warn-bg);color:var(--warn)}.chip.bad{background:var(--bad-bg);color:var(--bad)}\r\n.chip.wait{background:var(--wait-bg);color:var(--wait)}\r\n.ruler{position:relative;display:inline-grid;grid-template-columns:repeat(4,1fr);gap:2px;width:104px;height:8px;vertical-align:middle}\r\n.ruler i{border-radius:2px}.ruler i:nth-child(1){background:var(--bad-seg)}.ruler i:nth-child(2){background:var(--warn-seg)}\r\n.ruler i:nth-child(3){background:var(--ok-seg)}.ruler i:nth-child(4){background:var(--good-seg)}\r\n.ruler b{position:absolute;top:-5px;bottom:-5px;width:4px;margin-left:-2px;border-radius:2px;background:var(--ink);box-shadow:0 0 0 2px var(--surface)}\r\n.ruler.off i{background:var(--line)}\r\n.mut{color:var(--muted)}.prof.good{color:var(--good)}.prof.bad{color:var(--bad)}\r\n.recent{list-style:none;margin:0;padding:6px 0}.recent li{display:flex;justify-content:space-between;gap:10px;padding:10px 18px;border-bottom:1px solid #E8EDEB}\r\n.empty{padding:36px;text-align:center;color:var(--muted);display:grid;gap:10px;justify-items:center}\r\n.toast{position:fixed;left:50%;bottom:22px;transform:translate(-50%,16px);background:var(--btn);color:var(--btn-ink);padding:11px 16px;border-radius:10px;font-weight:700;opacity:0;pointer-events:none;transition:opacity .18s,transform .18s;z-index:50}\r\n.toast.on{opacity:1;transform:translate(-50%,0)}\r\n.cols{display:grid;grid-template-columns:minmax(0,640px) minmax(260px,1fr);gap:16px;align-items:start}\r\n@media(max-width:900px){.app{grid-template-columns:1fr}.side{height:auto;position:static;flex-direction:row;align-items:center}.cols,.two{grid-template-columns:1fr}}\r\n.daybar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:14px}\r\n.daybar .long{font-weight:700;font-size:17px;margin-left:8px}\r\n.daytbl td{padding:6px 8px}\r\n.ci{width:100%;min-width:76px;height:32px;padding:0 8px;border:1px solid var(--line);border-radius:7px;background:var(--surface);text-align:right}\r\n.ci:focus{outline:0;border-color:var(--ink)}\r\n.ci.bad{border-color:var(--bad)}\r\n.ci::placeholder{color:var(--muted);font-style:italic}\r\n.daytbl td.calc{background:#F4F7F6;text-align:right;white-space:nowrap;padding:0 10px}\r\n.savebar{position:sticky;bottom:0;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;padding:12px 18px;background:var(--surface);border-top:1px solid var(--line);border-radius:0 0 14px 14px}\r\n.bulkprev{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}\r\n.bulkprev span{background:#F4F7F6;border:1px solid var(--line);border-radius:99px;padding:2px 10px;font-size:12.5px}\r\n.bulkprev span.dup{border-color:var(--bad);color:var(--bad)}\r\n.warnbox{display:flex;gap:8px;align-items:flex-start;margin:0 18px 12px;font-size:12.5px;color:var(--warn);background:var(--warn-bg);border-radius:9px;padding:9px 10px}\r\n.scroll{overflow:auto;max-width:100%}\r\n</style>\r\n</head>\r\n<body>\r\n<div class=\"app\">\r\n  <aside class=\"side\">\r\n    <div class=\"brand\">Gestor de Tráfego</div>\r\n    <nav class=\"nav\" aria-label=\"Principal\">\r\n      <a href=\"#/criativos\" data-nav=\"criativos\">Criativos</a>\r\n      <a href=\"#/cadastro\" data-nav=\"cadastro\">Cadastro</a>\r\n      <a href=\"#/lancamento\" data-nav=\"lancamento\">Lançamento</a>\r\n    </nav>\r\n  </aside>\r\n  <main class=\"main\"><div class=\"wrap\" id=\"view\"></div></main>\r\n</div>\r\n<div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\r\n<script type=\"module\">\r\nimport * as Calc from \"/shared/calc.js\";\r\n\r\nconst $ = (s, r = document) => r.querySelector(s);\r\nconst $$ = (s, r = document) => Array.from(r.querySelectorAll(s));\r\nconst esc = (s) => String(s ?? \"\").replace(/[&<>\"']/g, (c) => ({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\r\nconst view = () => $(\"#view\");\r\nconst toast = (m) => { const t = $(\"#toast\"); t.textContent = m; t.classList.add(\"on\"); clearTimeout(t._h); t._h = setTimeout(() => t.classList.remove(\"on\"), 2600); };\r\nconst fDate = (s) => { const [y, m, d] = String(s).split(\"-\"); return `${d}/${m}/${y.slice(2)}`; };\r\nconst todayLocal = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,\"0\")}-${String(d.getDate()).padStart(2,\"0\")}`; };\r\n// Usa o módulo único de cálculo servido pelo servidor (ao-vivo + formato BR).\r\nconst fBRL = (cents) => Calc.formatBRL(cents);\r\n\r\nconst FORMAT = { video: \"Vídeo\", image: \"Imagem\", carousel: \"Carrossel\" };\r\nconst STATUS = { ativo: \"Ativo\", escalando: \"Escalando\", pausado: \"Pausado\", encerrado: \"Encerrado\" };\r\n\r\nfunction chipFor(h) {\r\n  const map = { \"Saudável\": \"ok\", \"Atenção\": \"warn\", \"Escalando\": \"good\", \"Pausado\": \"bad\", \"Encerrado\": \"bad\", \"Sem dados\": \"wait\" };\r\n  return `<span class=\"chip ${map[h.statusDisplay] ?? \"wait\"}\">${esc(h.statusDisplay)}</span>`;\r\n}\r\nfunction rulerFor(h) {\r\n  const pos = { vermelho: 12, amarelo: 37, azul: 62, verde: 87 };\r\n  if (h.ruler === \"cinza\") return `<span class=\"ruler off\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i></span>`;\r\n  return `<span class=\"ruler\" role=\"img\" aria-label=\"Saúde ${esc(h.statusDisplay)}\"><i></i><i></i><i></i><i></i><b style=\"left:${pos[h.ruler] ?? 62}%\"></b></span>`;\r\n}\r\nconst profitClass = (cents) => cents == null ? \"\" : cents >= 0 ? \"good\" : \"bad\";\r\nasync function api(path, opts) {\r\n  const res = await fetch(path, opts);\r\n  const body = await res.json().catch(() => ({}));\r\n  if (!res.ok) { const e = new Error(body.error || \"erro\"); e.status = res.status; e.body = body; throw e; }\r\n  return body;\r\n}\r\n\r\n// ---------- Biblioteca ----------\r\nconst L = { q: \"\", status: \"all\", sort: \"recent\" };\r\nasync function pageLibrary() {\r\n  view().innerHTML = `\r\n  <div class=\"ph\"><div><h1>Criativos</h1><p class=\"sub\" id=\"lib-sub\">Biblioteca mínima — T2</p></div><a class=\"btn\" href=\"#/cadastro\">+ Cadastrar criativo</a></div>\r\n  <div class=\"fb\">\r\n    <label class=\"ctl search\"><input id=\"lib-q\" placeholder=\"Buscar por nome ou produto\" value=\"${esc(L.q)}\" aria-label=\"Buscar criativo\"></label>\r\n    <label class=\"ctl\">Status <select id=\"lib-status\"><option value=\"all\">Todos</option>${Object.entries(STATUS).map(([k,v]) => `<option value=\"${k}\">${v}</option>`).join(\"\")}</select></label>\r\n    <label class=\"ctl\">Ordenar <select id=\"lib-sort\"><option value=\"recent\">Mais recentes</option><option value=\"name\">Nome A–Z</option><option value=\"profit\">Maior lucro</option></select></label>\r\n  </div>\r\n  <section class=\"panel\"><div class=\"panel-b\" id=\"lib-body\">Carregando…</div></section>`;\r\n  $(\"#lib-status\").value = L.status; $(\"#lib-sort\").value = L.sort;\r\n  $(\"#lib-q\").addEventListener(\"input\", (e) => { L.q = e.target.value; libBody(); });\r\n  $(\"#lib-status\").addEventListener(\"change\", (e) => { L.status = e.target.value; libBody(); });\r\n  $(\"#lib-sort\").addEventListener(\"change\", (e) => { L.sort = e.target.value; libBody(); });\r\n  $(\"#lib-body\").addEventListener(\"click\", (e) => { const tr = e.target.closest(\"tr[data-id]\"); if (tr) location.hash = \"#/criativo/\" + tr.dataset.id; });\r\n  await libBody();\r\n}\r\nasync function libBody() {\r\n  const box = $(\"#lib-body\");\r\n  try {\r\n    const qs = new URLSearchParams();\r\n    if (L.q.trim()) qs.set(\"q\", L.q.trim());\r\n    if (L.status !== \"all\") qs.set(\"status\", L.status);\r\n    const { data } = await api(\"/api/creatives?\" + qs.toString());\r\n    let rows = [...data];\r\n    if (L.sort === \"name\") rows.sort((a, b) => a.name.localeCompare(b.name, \"pt-BR\"));\r\n    else if (L.sort === \"profit\") rows.sort((a, b) => (b.totals.profit_cents ?? -Infinity) - (a.totals.profit_cents ?? -Infinity));\r\n    else rows.sort((a, b) => b.start_date.localeCompare(a.start_date) || b.id - a.id);\r\n    $(\"#lib-sub\").textContent = `${rows.length} criativo(s) na biblioteca`;\r\n    if (!rows.length) { box.innerHTML = `<div class=\"empty\"><strong>Nenhum criativo encontrado</strong><span>Tente outra busca ou cadastre um novo.</span><a class=\"btn\" href=\"#/cadastro\">Cadastrar criativo</a></div>`; return; }\r\n    box.innerHTML = `<div style=\"overflow:auto\"><table class=\"tbl\"><thead><tr><th>Criativo</th><th>Status</th><th>Início</th><th class=\"num\">Investimento</th><th class=\"num\">Lucro</th><th>Saúde do dia</th><th>Motivo</th></tr></thead><tbody>${rows.map((c) => {\r\n      const pc = profitClass(c.totals.profit_cents);\r\n      return `<tr class=\"click\" data-id=\"${c.id}\"><td><div class=\"nm\">${esc(c.name)}</div><div class=\"sub\">${esc(c.product || \"—\")} · ${FORMAT[c.format] ?? c.format}</div></td><td>${chipFor(c.health)}</td><td>${fDate(c.start_date)}</td><td class=\"num\">${fBRL(c.totals.investment_cents)}</td><td class=\"num prof ${pc}\">${fBRL(c.totals.profit_cents)}</td><td>${rulerFor(c.health)}</td><td class=\"mut\">${esc(c.health.motivo ?? \"—\")}</td></tr>`;\r\n    }).join(\"\")}</tbody></table></div>`;\r\n  } catch { box.innerHTML = `<div class=\"empty\"><strong>Não foi possível carregar</strong></div>`; }\r\n}\r\n\r\n// ---------- Cadastro (T2 único + T3 em lote) ----------\r\n// produto/formato/data mantidos após cada cadastro para encadear o próximo.\r\nconst R = { mode: \"single\", name: \"\", bulk: \"\", product: \"\", format: \"video\", start: todayLocal(), status: \"ativo\", url: \"\", notes: \"\" };\r\nconst bulkNames = () => R.bulk.split(\"\\n\").map((s) => s.trim()).filter(Boolean);\r\nasync function pageRegister() {\r\n  let products = [];\r\n  let existing = [];\r\n  try { const { data } = await api(\"/api/creatives\"); products = [...new Set(data.map((c) => c.product).filter(Boolean))].sort((a,b)=>a.localeCompare(b,\"pt-BR\")); existing = data.map((c) => ({ name: c.name, status: c.status })); } catch {}\r\n  const bulk = R.mode === \"bulk\";\r\n  const isFuture = R.start > todayLocal();\r\n  view().innerHTML = `\r\n  <div class=\"ph\"><div><h1>Cadastro</h1><p class=\"sub\">Registre os criativos novos. Os números do dia entram depois, no lançamento.</p></div></div>\r\n  <div class=\"cols\">\r\n  <section class=\"panel\"><div class=\"panel-b\">\r\n    <div class=\"seg\" role=\"group\" aria-label=\"Modo de cadastro\"><button type=\"button\" data-mode=\"single\" aria-pressed=\"${!bulk}\">Um criativo</button><button type=\"button\" data-mode=\"bulk\" aria-pressed=\"${bulk}\">Vários de uma vez</button></div>\r\n    <div style=\"height:14px\"></div>\r\n    ${bulk\r\n      ? `<div class=\"fld\"><label for=\"r-bulk\">Nomes dos criativos (um por linha)</label><textarea class=\"in\" id=\"r-bulk\" rows=\"6\" placeholder=\"Depoimento cozinha 03&#10;UGC achadinho 04\">${esc(R.bulk)}</textarea><div class=\"bulkprev\" id=\"r-prev\" aria-live=\"polite\"></div><div class=\"err-msg\" id=\"r-err\" hidden></div></div>`\r\n      : `<div class=\"fld\"><label for=\"r-name\">Nome do criativo</label><input class=\"in\" id=\"r-name\" value=\"${esc(R.name)}\" placeholder=\"Ex.: Depoimento cozinha 03\" autocomplete=\"off\"><div class=\"err-msg\" id=\"r-err\" hidden></div></div>`}\r\n    <div class=\"fld\"><label for=\"r-product\">Produto ou oferta</label><input class=\"in\" id=\"r-product\" list=\"r-products\" value=\"${esc(R.product)}\" placeholder=\"Ex.: Mini processador\" autocomplete=\"off\"><datalist id=\"r-products\">${products.map((p)=>`<option value=\"${esc(p)}\">`).join(\"\")}</datalist><span class=\"hint\">Mantido após cadastrar para encadear o próximo.</span></div>\r\n    <div class=\"fld\"><span class=\"l\" style=\"font-weight:700\">Formato</span><div class=\"seg\" role=\"group\" aria-label=\"Formato\">${Object.entries(FORMAT).map(([k,v])=>`<button type=\"button\" data-format=\"${k}\" aria-pressed=\"${R.format===k}\">${v}</button>`).join(\"\")}</div></div>\r\n    <div class=\"two\">\r\n      <div class=\"fld\"><label for=\"r-start\">Data de início</label><input type=\"date\" class=\"in\" id=\"r-start\" value=\"${esc(R.start)}\"><span class=\"hint\">Mantida após cadastrar.</span></div>\r\n      <div class=\"fld\"><label for=\"r-status\">Status inicial</label><select class=\"in\" id=\"r-status\">${Object.entries(STATUS).map(([k,v])=>`<option value=\"${k}\">${v}</option>`).join(\"\")}</select></div>\r\n    </div>\r\n    ${isFuture ? `<p class=\"hint\" id=\"r-pre\">Pré-cadastro: começa em ${fDate(R.start)} — não conta Dia 1 nem dispara Sinal até ter movimento.</p>` : ``}\r\n    ${bulk ? `` : `\r\n    <div class=\"fld\"><label for=\"r-url\">Link do Criativo (opcional)</label><input class=\"in\" id=\"r-url\" type=\"url\" value=\"${esc(R.url)}\" placeholder=\"Pasta do Drive ou link do Criativo\"></div>\r\n    <div class=\"fld\"><label for=\"r-notes\">Observações (opcional)</label><textarea class=\"in\" id=\"r-notes\" placeholder=\"Gancho, ângulo, público…\">${esc(R.notes)}</textarea></div>`}\r\n    <div class=\"actions\"><button class=\"btn\" id=\"r-save\" type=\"button\"><span id=\"r-save-l\">Cadastrar</span></button><button class=\"btn ghost\" id=\"r-save-go\" type=\"button\">Cadastrar e lançar dados</button></div>\r\n  </div></section>\r\n  <section class=\"panel\"><div class=\"panel-b\"><strong>Últimos cadastrados</strong></div><ul class=\"recent\" id=\"r-recent\"><li class=\"mut\">Carregando…</li></ul></section>\r\n  </div>`;\r\n  $(\"#r-status\").value = R.status;\r\n  const errEl = () => $(\"#r-err\");\r\n  const showErr = (m, sel) => { const e = errEl(); e.textContent = m; e.hidden = false; const i = sel ? $(sel) : null; if (i) { i.classList.add(\"err\"); i.focus(); } };\r\n  const clearErr = () => { const e = errEl(); if (e) e.hidden = true; $$(\".in.err\").forEach((i)=>i.classList.remove(\"err\")); };\r\n  const paintPreview = () => {\r\n    const box = $(\"#r-prev\");\r\n    if (!box) { const l = $(\"#r-save-l\"); if (l) l.textContent = \"Cadastrar\"; return; }\r\n    const names = bulkNames();\r\n    const taken = new Set(existing.filter((c) => c.status !== \"encerrado\").map((c) => String(c.name).toLowerCase()));\r\n    const seen = new Set();\r\n    box.innerHTML = names.map((n) => {\r\n      const k = n.toLowerCase();\r\n      const dup = taken.has(k) || seen.has(k);\r\n      seen.add(k);\r\n      return `<span class=\"${dup ? \"dup\" : \"\"}\">${esc(n)}</span>`;\r\n    }).join(\"\");\r\n    $(\"#r-save-l\").textContent = names.length > 1 ? `Cadastrar ${names.length} criativos` : \"Cadastrar\";\r\n  };\r\n  $$(\"[data-mode]\").forEach((b) => b.addEventListener(\"click\", () => { R.mode = b.dataset.mode; pageRegister(); }));\r\n  const nameInput = $(\"#r-name\");\r\n  if (nameInput) nameInput.addEventListener(\"input\", (e) => { R.name = e.target.value; clearErr(); });\r\n  const bulkInput = $(\"#r-bulk\");\r\n  if (bulkInput) bulkInput.addEventListener(\"input\", (e) => { R.bulk = e.target.value; clearErr(); paintPreview(); });\r\n  $(\"#r-product\").addEventListener(\"input\", (e) => { R.product = e.target.value; });\r\n  $(\"#r-start\").addEventListener(\"change\", (e) => { R.start = e.target.value || todayLocal(); pageRegister(); });\r\n  $(\"#r-status\").addEventListener(\"change\", (e) => { R.status = e.target.value; });\r\n  const urlInput = $(\"#r-url\");\r\n  if (urlInput) urlInput.addEventListener(\"input\", (e) => { R.url = e.target.value; });\r\n  const notesInput = $(\"#r-notes\");\r\n  if (notesInput) notesInput.addEventListener(\"input\", (e) => { R.notes = e.target.value; });\r\n  $$(\"[data-format]\").forEach((b) => b.addEventListener(\"click\", () => { R.format = b.dataset.format; $$(\"[data-format]\").forEach((x)=>x.setAttribute(\"aria-pressed\", x===b)); }));\r\n  $(\"#r-save\").addEventListener(\"click\", () => submitRegister(false, showErr));\r\n  $(\"#r-save-go\").addEventListener(\"click\", () => submitRegister(true, showErr));\r\n  paintPreview();\r\n  await paintRecent();\r\n}\r\nasync function paintRecent() {\r\n  try {\r\n    const { data } = await api(\"/api/creatives\");\r\n    const last = [...data].sort((a,b)=>b.id-a.id).slice(0,6);\r\n    $(\"#r-recent\").innerHTML = last.length ? last.map((c)=>`<li><div><a href=\"#/criativo/${c.id}\">${esc(c.name)}</a><div class=\"sub\">${esc(c.product||\"—\")} · ${FORMAT[c.format]} · ${fDate(c.start_date)}</div></div>${chipFor(c.health)}</li>`).join(\"\") : `<li class=\"mut\">Nenhum criativo ainda.</li>`;\r\n  } catch { const el = $(\"#r-recent\"); if (el) el.innerHTML = `<li class=\"mut\">—</li>`; }\r\n}\r\nasync function submitRegister(goDaily, err) {\r\n  if (R.mode === \"bulk\") {\r\n    const names = bulkNames();\r\n    if (!names.length) { err(\"Digite pelo menos um nome, um por linha.\", \"#r-bulk\"); return; }\r\n    try {\r\n      const { data } = await api(\"/api/creatives/bulk\", { method: \"POST\", headers: {\"content-type\":\"application/json\"}, body: JSON.stringify({ names, product: R.product.trim(), format: R.format, start_date: R.start, status: R.status }) });\r\n      // Mantém produto/formato/data para encadear; limpa só a lista.\r\n      R.bulk = \"\";\r\n      toast(data.length === 1 ? `Criativo cadastrado: ${data[0].name}` : `${data.length} criativos cadastrados`);\r\n      if (goDaily) { location.hash = \"#/lancamento\"; } else { pageRegister(); const f = $(\"#r-bulk\"); if (f) f.focus(); }\r\n    } catch (e) {\r\n      const warns = e.body?.warnings ?? [];\r\n      if (e.body?.error === \"nome_duplicado\") err(warns[0] || \"Há nomes repetidos ou já cadastrados (em vermelho).\", \"#r-bulk\");\r\n      else err(\"Não foi possível cadastrar. Confira os campos.\", \"#r-bulk\");\r\n    }\r\n    return;\r\n  }\r\n  const payload = { name: R.name.trim(), product: R.product.trim(), format: R.format, start_date: R.start, status: R.status, url: R.url.trim(), notes: R.notes };\r\n  if (!payload.name) { err(\"Informe o nome do criativo.\", \"#r-name\"); return; }\r\n  try {\r\n    const { data } = await api(\"/api/creatives\", { method: \"POST\", headers: {\"content-type\":\"application/json\"}, body: JSON.stringify(payload) });\r\n    // Mantém produto/formato/data para encadear; limpa só nome/link/observações.\r\n    R.name = \"\"; R.url = \"\"; R.notes = \"\";\r\n    toast(`Criativo cadastrado: ${data.name}`);\r\n    if (goDaily) { location.hash = \"#/lancamento\"; } else { pageRegister(); const f = $(\"#r-name\"); if (f) f.focus(); }\r\n  } catch (e) {\r\n    const warns = e.body?.warnings ?? [];\r\n    if (e.body?.error === \"nome_duplicado\") err(warns[0] || \"Já existe um criativo com esse nome.\", \"#r-name\");\r\n    else err(\"Não foi possível cadastrar. Confira os campos.\", \"#r-name\");\r\n  }\r\n}\r\n\r\n// ---------- Detalhe mínimo (réplica-da-planilha chega no T4) ----------\r\nasync function pageDetail(id) {\r\n  try {\r\n    const { data: c } = await api(\"/api/creatives/\" + id);\r\n    const pc = profitClass(c.totals.profit_cents);\r\n    view().innerHTML = `\r\n    <a href=\"#/criativos\" style=\"color:var(--muted);text-decoration:none\">← Criativos</a>\r\n    <div class=\"ph\"><div><h1>${esc(c.name)}</h1><p class=\"sub\">${esc(c.product||\"—\")} · ${FORMAT[c.format]} · início em ${fDate(c.start_date)}</p></div><div>${chipFor(c.health)}</div></div>\r\n    <section class=\"panel\"><div class=\"panel-b\" style=\"display:flex;gap:24px;flex-wrap:wrap;align-items:center\">${rulerFor(c.health)}<span><strong class=\"prof ${pc}\">${fBRL(c.totals.profit_cents)}</strong> <span class=\"mut\">lucro · ${fBRL(c.totals.investment_cents)} investidos · ${c.totals.sales} vendas</span></span><span class=\"mut\">${esc(c.health.motivo ?? (c.health.dia1 ? \"—\" : \"Pré-cadastro: sem Dia 1, sem Sinal até ter movimento.\"))}</span></div></section>\r\n    <section class=\"panel\"><div class=\"panel-b\"><strong>Lançamentos diários</strong><p class=\"sub\">A planilha editável (TOTAL, filtro por mês, adicionar dia) chega no T4.</p><div class=\"actions\"><a class=\"btn ghost\" href=\"#/lancamento\">Ir para lançamento</a></div></div></section>`;\r\n  } catch { location.hash = \"#/criativos\"; }\r\n}\r\n// ---------- Lançamento diário em lote (T3) ----------\n// Um dia, todos os Ativos numa tabela só. Tudo recalcula ao digitar via Calc.\nconst DY = { date: todayLocal() };\nconst fmtInputCents = (cents) => cents == null ? \"\" : (cents / 100).toLocaleString(\"pt-BR\", { minimumFractionDigits: 2, maximumFractionDigits: 2 });\nfunction pageDaily() {\n  view().innerHTML = `\n  <div class=\"ph\"><div><h1>Lançamento diário</h1><p class=\"sub\">Lance o dia de todos os Ativos numa tabela só.</p></div><a class=\"btn ghost\" href=\"#/cadastro\">Cadastrar criativo</a></div>\n  <div class=\"daybar\">\n    <button class=\"btn ghost sm\" id=\"dy-prev\" type=\"button\" aria-label=\"Dia anterior\">←</button>\n    <input type=\"date\" class=\"in sm\" id=\"dy-date\" style=\"width:auto\" aria-label=\"Data do lançamento\">\n    <button class=\"btn ghost sm\" id=\"dy-next\" type=\"button\" aria-label=\"Próximo dia\">→</button>\n    <button class=\"btn ghost sm\" id=\"dy-today\" type=\"button\">Hoje</button>\n    <span class=\"long\" id=\"dy-long\"></span>\n  </div>\n  <section class=\"panel\"><div class=\"scroll\" id=\"dy-body\"><div class=\"panel-b mut\">Carregando…</div></div>\n    <div class=\"warnbox\" id=\"dy-warn\" hidden></div>\n    <div class=\"savebar\"><span id=\"dy-count\" class=\"mut\"></span><button class=\"btn\" id=\"dy-save\" type=\"button\">Salvar lançamentos</button></div></section>`;\n  const go = (d) => { if (!d || d > todayLocal()) return; DY.date = d; renderDay(); };\r\n  $(\"#dy-date\").max = todayLocal();\n  $(\"#dy-prev\").addEventListener(\"click\", () => {\n    const [y, m, d] = DY.date.split(\"-\").map(Number);\n    const dt = new Date(Date.UTC(y, m - 1, d - 1));\n    go(dt.toISOString().slice(0, 10));\n  });\n  $(\"#dy-next\").addEventListener(\"click\", () => {\n    const [y, m, d] = DY.date.split(\"-\").map(Number);\n    const dt = new Date(Date.UTC(y, m - 1, d + 1));\n    const iso = dt.toISOString().slice(0, 10);\n    if (iso <= todayLocal()) go(iso);\n  });\n  $(\"#dy-today\").addEventListener(\"click\", () => go(todayLocal()));\n  $(\"#dy-date\").addEventListener(\"change\", (e) => go(e.target.value));\n  $(\"#dy-save\").addEventListener(\"click\", saveDay);\n  const body = $(\"#dy-body\");\n  body.addEventListener(\"input\", (ev) => { const tr = ev.target.closest(\"tr[data-cid]\"); if (tr) { paintDayRow(tr); countDay(); } });\n  body.addEventListener(\"keydown\", (ev) => {\n    if (ev.key !== \"Enter\" || !ev.target.matches(\"input[data-f]\")) return;\n    ev.preventDefault();\n    const nxt = ev.target.closest(\"tr\").nextElementSibling;\n    const t = nxt ? nxt.querySelector(`input[data-f=\"${ev.target.dataset.f}\"]`) : null;\n    if (t) { t.focus(); t.select(); } else $(\"#dy-save\").focus();\n  });\n  renderDay();\n}\nasync function renderDay() {\n  const date = DY.date;\n  $(\"#dy-date\").value = date;\n  $(\"#dy-next\").disabled = date >= todayLocal();\n  const [y, m, d] = date.split(\"-\");\n  $(\"#dy-long\").textContent = `${d}/${m}/${y.slice(2)}`;\n  const box = $(\"#dy-body\");\n  try {\n    const { data } = await api(\"/api/entries?date=\" + date);\n    if (!data.length) {\n      box.innerHTML = `<div class=\"empty\"><strong>Nenhum criativo ativo</strong><span>Cadastre um criativo ou mude o status para Ativo/Escalando.</span><a class=\"btn\" href=\"#/cadastro\">Cadastrar criativo</a></div>`;\n      $(\"#dy-save\").disabled = true; $(\"#dy-count\").textContent = \"\";\n      return;\n    }\n    const cell = (f, val, mode, ph) => `<td><input class=\"ci\" data-f=\"${f}\" inputmode=\"${mode}\" value=\"${esc(val)}\" placeholder=\"${esc(ph)}\"></td>`;\n    box.innerHTML = `<table class=\"tbl daytbl\"><thead><tr><th>Criativo</th><th class=\"num\">Invest. (R$)</th><th class=\"num\">Vendas</th><th class=\"num\">Fatur. (R$)</th><th class=\"num\">Cliques Meta</th><th class=\"num\">Cliques Shopee</th><th class=\"num\">Custo</th><th class=\"num\">Lucro</th><th class=\"num\">CPC Meta</th><th class=\"num\">CPC Shopee</th><th>Saúde</th></tr></thead><tbody>${data.map((r) => {\n      const e = r.entry;\n      return `<tr data-cid=\"${r.creative.id}\" data-tax=\"${r.tax_rate}\" data-dia1=\"${esc(r.dia1 ?? \"\")}\"><td><div class=\"nm\">${esc(r.creative.name)}</div><div class=\"sub\">${esc(r.creative.product || \"—\")}</div></td>`\n        + cell(\"invest\", e ? fmtInputCents(e.investment_cents) : \"\", \"decimal\", \"0,00\")\n        + cell(\"sales\", e ? String(e.sales) : \"\", \"numeric\", \"0\")\n        + cell(\"rev\", e && e.revenue_cents != null ? fmtInputCents(e.revenue_cents) : \"\", \"decimal\", \"pendente\")\n        + cell(\"clM\", e ? String(e.clicks_meta) : \"\", \"numeric\", \"0\")\n        + cell(\"clS\", e ? String(e.clicks_shopee) : \"\", \"numeric\", \"0\")\n        + `<td class=\"calc\" data-c=\"cost\">—</td><td class=\"calc\" data-c=\"profit\">—</td><td class=\"calc\" data-c=\"cpcM\">—</td><td class=\"calc\" data-c=\"cpcS\">—</td><td class=\"mut\" data-c=\"health\">—</td></tr>`;\n    }).join(\"\")}</tbody></table>`;\n    $$(\"#dy-body tr[data-cid]\").forEach(paintDayRow);\n    countDay();\n    const w = $(\"#dy-warn\"); if (w) w.hidden = true;\n  } catch {\n    box.innerHTML = `<div class=\"empty\"><strong>Não foi possível carregar o dia</strong></div>`;\n  }\n}\nfunction paintDayRow(tr) {\n  const tax = Number(tr.dataset.tax || 0.1386);\n  const date = DY.date;\n  const dia1 = tr.dataset.dia1 || null;\n  const inv = Calc.parseMoedaParaCentavos($('[data-f=\"invest\"]', tr).value);\n  const rev = Calc.parseMoedaParaCentavos($('[data-f=\"rev\"]', tr).value);\n  const sales = Calc.parseInteiro($('[data-f=\"sales\"]', tr).value);\n  const clM = Calc.parseInteiro($('[data-f=\"clM\"]', tr).value);\n  const clS = Calc.parseInteiro($('[data-f=\"clS\"]', tr).value);\n  const invC = inv == null ? 0 : inv;\n  const salesN = sales == null ? 0 : sales;\n  const clMN = clM == null ? 0 : clM;\n  const clSN = clS == null ? 0 : clS;\n  const bad = [inv, sales, clM, clS].some((v) => typeof v === \"number\" && Number.isNaN(v)) || (rev != null && Number.isNaN(rev));\r\n  // Módulo único de cálculo (spec #6): custo/lucro/CPCs/pendente vêm do Calc.\r\n  const row = bad ? null : Calc.calcRow({ date, investment_cents: invC, sales: salesN, revenue_cents: rev, clicks_meta: clMN, clicks_shopee: clSN, tax_rate: tax });\r\n  const cost = row ? row.cost_cents : null;\r\n  const isPending = row ? row.is_pending : false;\r\n  const profit = row ? row.profit_cents : null;\r\n  const cpcM = row ? row.cpc_meta_cents : null;\r\n  const cpcS = row ? row.cpc_shopee_cents : null;\n  $('[data-c=\"cost\"]', tr).textContent = Calc.formatBRL(cost);\n  const pEl = $('[data-c=\"profit\"]', tr);\n  pEl.textContent = isPending ? \"pendente\" : Calc.formatBRL(profit);\n  pEl.className = \"calc\" + (profit == null || isPending ? \"\" : profit >= 0 ? \" prof good\" : \" prof bad\");\n  $('[data-c=\"cpcM\"]', tr).textContent = Calc.formatCPC(cpcM);\n  $('[data-c=\"cpcS\"]', tr).textContent = Calc.formatCPC(cpcS);\n  const hEl = $('[data-c=\"health\"]', tr);\n  if (bad || (invC === 0 && salesN === 0 && clMN === 0 && clSN === 0 && rev == null)) { hEl.textContent = \"—\"; return; }\n  try {\n    const isDia1 = !dia1 || date <= dia1;\n    const sig = Calc.evaluateDay({ date, investment_cents: invC, sales: salesN, revenue_cents: rev, clicks_meta: clMN, clicks_shopee: clSN, tax_rate: tax }, isDia1);\n    hEl.textContent = sig.saude === \"atencao\" ? `Atenção · ${sig.motivo ?? \"\"}` : (sig.motivo ?? \"Saudável\");\n  } catch { hEl.textContent = \"—\"; }\n}\nconst rowFilled = (tr) => [\"invest\", \"sales\", \"rev\", \"clM\", \"clS\"].some((f) => $('[data-f=\"' + f + '\"]', tr).value.trim() !== \"\");\nfunction countDay() {\n  const rows = $$(\"#dy-body tr[data-cid]\");\n  if (!rows.length) return;\n  const n = rows.filter(rowFilled).length;\n  $(\"#dy-count\").textContent = `${n} de ${rows.length} preenchidos`;\n  $(\"#dy-save\").disabled = n === 0;\n}\nasync function saveDay() {\n  const rows = $$(\"#dy-body tr[data-cid]\");\n  const entries = [];\n  $$(\"#dy-body .ci.bad\").forEach((i) => i.classList.remove(\"bad\"));\n  for (const tr of rows) {\n    if (!rowFilled(tr)) continue;\n    const cid = Number(tr.dataset.cid);\n    const inv = Calc.parseMoedaParaCentavos($('[data-f=\"invest\"]', tr).value);\n    const rev = Calc.parseMoedaParaCentavos($('[data-f=\"rev\"]', tr).value);\n    const sales = Calc.parseInteiro($('[data-f=\"sales\"]', tr).value);\n    const clM = Calc.parseInteiro($('[data-f=\"clM\"]', tr).value);\n    const clS = Calc.parseInteiro($('[data-f=\"clS\"]', tr).value);\n    const name = $(\".nm\", tr).textContent;\n    const mark = (f) => $('[data-f=\"' + f + '\"]', tr).classList.add(\"bad\");\n    let bad = false;\n    for (const [f, v] of [[\"invest\", inv], [\"sales\", sales], [\"rev\", rev], [\"clM\", clM], [\"clS\", clS]]) {\n      if (typeof v === \"number\" && Number.isNaN(v)) { mark(f); bad = true; }\n      if (typeof v === \"number\" && v != null && v < 0) { mark(f); bad = true; }\n    }\n    for (const [f, v] of [[\"sales\", sales], [\"clM\", clM], [\"clS\", clS]]) {\n      if (typeof v === \"number\" && v != null && !Number.isInteger(v)) { mark(f); bad = true; }\n    }\n    if (bad) { toast(`Confira os números de ${name}.`); return; }\n    entries.push({ creative_id: cid, investment_cents: inv ?? 0, sales: sales ?? 0, revenue_cents: rev, clicks_meta: clM ?? 0, clicks_shopee: clS ?? 0 });\n  }\n  if (!entries.length) { toast(\"Preencha ao menos um criativo.\"); return; }\n  try {\n    const { warnings } = await api(\"/api/entries/bulk\", { method: \"POST\", headers: {\"content-type\":\"application/json\"}, body: JSON.stringify({ date: DY.date, entries }) });\n    const w = $(\"#dy-warn\");\n    if (warnings?.length) { w.textContent = warnings.join(\" \"); w.hidden = false; }\n    else if (w) w.hidden = true;\n    toast(`${entries.length} ${entries.length === 1 ? \"lançamento salvo\" : \"lançamentos salvos\"} em ${fDate(DY.date)}`);\n    renderDay();\n  } catch (e) {\n    toast(e.body?.error === \"encerrado_sem_lancamento\" ? \"Criativo encerrado não recebe lançamentos.\" : \"Não foi possível salvar. Confira os números (nada negativo; vendas/cliques inteiros).\");\n  }\n}\n\nfunction router() {\r\n  $$(\".nav a\").forEach((a) => a.removeAttribute(\"aria-current\"));\r\n  const h = location.hash || \"#/criativos\";\r\n  if (h.startsWith(\"#/cadastro\")) { $('[data-nav=\"cadastro\"]').setAttribute(\"aria-current\",\"page\"); pageRegister(); }\r\n  else if (h.startsWith(\"#/criativo/\")) { $('[data-nav=\"criativos\"]').setAttribute(\"aria-current\",\"page\"); pageDetail(h.split(\"/\")[2]); }\r\n  else if (h.startsWith(\"#/lancamento\")) { $('[data-nav=\"lancamento\"]').setAttribute(\"aria-current\",\"page\"); pageDaily(); }\r\n  else { $('[data-nav=\"criativos\"]').setAttribute(\"aria-current\",\"page\"); pageLibrary(); }\r\n}\r\nwindow.addEventListener(\"hashchange\", router);\r\nrouter();\r\n</script>\r\n</body>\r\n</html>\r\n", binary: undefined },
};
export const INDEX_HTML: string = "<!DOCTYPE html>\r\n<html lang=\"pt-BR\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n<title>Gestor de Tráfego Pago</title>\r\n<style>\r\n:root{--bg:#EBEFED;--surface:#fff;--ink:#16201C;--muted:#647570;--line:#D8DFDC;--btn:#16201C;--btn-ink:#fff;\r\n--good:#0B8A4C;--good-bg:#D9F2E4;--good-seg:#2FBF7A;--ok:#0E76B8;--ok-bg:#D8ECF9;--ok-seg:#3AA6E6;\r\n--warn:#8A5F00;--warn-bg:#F6E8BE;--warn-seg:#E2AE1F;--bad:#B72929;--bad-bg:#F8DADA;--bad-seg:#E5595B;--wait-bg:#E3E9E6;--wait:#5D6D68}\r\n*{box-sizing:border-box}\r\nbody{margin:0;background:var(--bg);color:var(--ink);font:400 14px/1.45 system-ui,\"Segoe UI\",Roboto,Arial,sans-serif;padding:0}\r\n.app{display:grid;grid-template-columns:220px minmax(0,1fr);min-height:100vh}\r\n.side{background:var(--surface);border-right:1px solid var(--line);padding:18px 12px;display:flex;flex-direction:column;gap:2px;position:sticky;top:0;height:100vh}\r\n.brand{font-weight:800;font-size:17px;padding:4px 10px 16px}\r\n.nav{display:flex;flex-direction:column;gap:2px}\r\n.nav a{padding:9px 10px;border-radius:9px;text-decoration:none;color:#3A4843;font-weight:600}\r\n.nav a[aria-current=\"page\"]{background:var(--btn);color:var(--btn-ink)}\r\n.main{padding:26px 28px 56px;min-width:0}\r\n.wrap{max-width:1100px;margin:0 auto}\r\n.ph{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;flex-wrap:wrap;margin-bottom:16px}\r\n.ph h1{margin:0;font-size:28px}\r\n.sub{color:var(--muted);font-size:13px;margin:4px 0 0}\r\n.panel{background:var(--surface);border:1px solid var(--line);border-radius:14px;margin-bottom:16px}\r\n.panel-b{padding:18px}\r\n.fb{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}\r\n.ctl{display:inline-flex;align-items:center;gap:8px;height:38px;padding:0 12px;border:1px solid var(--line);border-radius:9px;background:var(--surface)}\r\n.ctl input,.ctl select{border:0;background:transparent;outline:0}\r\n.ctl.search{min-width:240px}.ctl.search input{flex:1}\r\n.btn{display:inline-flex;align-items:center;gap:8px;height:38px;padding:0 14px;border-radius:9px;border:1px solid var(--btn);background:var(--btn);color:var(--btn-ink);font-weight:700;cursor:pointer;text-decoration:none}\r\n.btn.ghost{background:transparent;color:var(--ink);border-color:var(--line)}\r\n.btn:disabled{opacity:.4;cursor:not-allowed}\r\n.in{height:40px;width:100%;padding:0 12px;border:1px solid var(--line);border-radius:9px;background:var(--surface)}\r\ntextarea.in{height:auto;min-height:80px;padding:10px 12px;resize:vertical}\r\n.in.err{border-color:var(--bad)}\r\n.fld{display:grid;gap:6px;margin-bottom:14px}.fld>label{font-weight:700}\r\n.hint{font-size:12.5px;color:var(--muted)}\r\n.err-msg{font-size:13px;color:var(--bad);font-weight:700}\r\n.seg{display:inline-flex;border:1px solid var(--line);border-radius:9px;padding:3px;background:#F4F7F6;gap:2px}\r\n.seg button{height:32px;padding:0 14px;border:0;border-radius:7px;background:transparent;cursor:pointer;font-weight:600}\r\n.seg button[aria-pressed=\"true\"]{background:var(--surface);box-shadow:0 0 0 1px var(--line)}\r\n.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}\r\n.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:6px}\r\n.tbl{width:100%;border-collapse:collapse}\r\n.tbl th{font-size:12px;color:var(--muted);text-align:left;padding:10px 12px;border-bottom:1px solid var(--line);white-space:nowrap}\r\n.tbl td{padding:11px 12px;border-bottom:1px solid #E8EDEB;vertical-align:middle}\r\n.tbl tr.click{cursor:pointer}.tbl tr.click:hover td{background:#F4F7F6}\r\n.tbl td.num,.tbl th.num{text-align:right}\r\n.nm{font-weight:700}\r\n.chip{display:inline-flex;align-items:center;height:24px;padding:0 10px;border-radius:99px;font-size:12px;font-weight:800;white-space:nowrap}\r\n.chip.good{background:var(--good-bg);color:var(--good)}.chip.ok{background:var(--ok-bg);color:var(--ok)}\r\n.chip.warn{background:var(--warn-bg);color:var(--warn)}.chip.bad{background:var(--bad-bg);color:var(--bad)}\r\n.chip.wait{background:var(--wait-bg);color:var(--wait)}\r\n.ruler{position:relative;display:inline-grid;grid-template-columns:repeat(4,1fr);gap:2px;width:104px;height:8px;vertical-align:middle}\r\n.ruler i{border-radius:2px}.ruler i:nth-child(1){background:var(--bad-seg)}.ruler i:nth-child(2){background:var(--warn-seg)}\r\n.ruler i:nth-child(3){background:var(--ok-seg)}.ruler i:nth-child(4){background:var(--good-seg)}\r\n.ruler b{position:absolute;top:-5px;bottom:-5px;width:4px;margin-left:-2px;border-radius:2px;background:var(--ink);box-shadow:0 0 0 2px var(--surface)}\r\n.ruler.off i{background:var(--line)}\r\n.mut{color:var(--muted)}.prof.good{color:var(--good)}.prof.bad{color:var(--bad)}\r\n.recent{list-style:none;margin:0;padding:6px 0}.recent li{display:flex;justify-content:space-between;gap:10px;padding:10px 18px;border-bottom:1px solid #E8EDEB}\r\n.empty{padding:36px;text-align:center;color:var(--muted);display:grid;gap:10px;justify-items:center}\r\n.toast{position:fixed;left:50%;bottom:22px;transform:translate(-50%,16px);background:var(--btn);color:var(--btn-ink);padding:11px 16px;border-radius:10px;font-weight:700;opacity:0;pointer-events:none;transition:opacity .18s,transform .18s;z-index:50}\r\n.toast.on{opacity:1;transform:translate(-50%,0)}\r\n.cols{display:grid;grid-template-columns:minmax(0,640px) minmax(260px,1fr);gap:16px;align-items:start}\r\n@media(max-width:900px){.app{grid-template-columns:1fr}.side{height:auto;position:static;flex-direction:row;align-items:center}.cols,.two{grid-template-columns:1fr}}\r\n.daybar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:14px}\r\n.daybar .long{font-weight:700;font-size:17px;margin-left:8px}\r\n.daytbl td{padding:6px 8px}\r\n.ci{width:100%;min-width:76px;height:32px;padding:0 8px;border:1px solid var(--line);border-radius:7px;background:var(--surface);text-align:right}\r\n.ci:focus{outline:0;border-color:var(--ink)}\r\n.ci.bad{border-color:var(--bad)}\r\n.ci::placeholder{color:var(--muted);font-style:italic}\r\n.daytbl td.calc{background:#F4F7F6;text-align:right;white-space:nowrap;padding:0 10px}\r\n.savebar{position:sticky;bottom:0;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;padding:12px 18px;background:var(--surface);border-top:1px solid var(--line);border-radius:0 0 14px 14px}\r\n.bulkprev{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}\r\n.bulkprev span{background:#F4F7F6;border:1px solid var(--line);border-radius:99px;padding:2px 10px;font-size:12.5px}\r\n.bulkprev span.dup{border-color:var(--bad);color:var(--bad)}\r\n.warnbox{display:flex;gap:8px;align-items:flex-start;margin:0 18px 12px;font-size:12.5px;color:var(--warn);background:var(--warn-bg);border-radius:9px;padding:9px 10px}\r\n.scroll{overflow:auto;max-width:100%}\r\n</style>\r\n</head>\r\n<body>\r\n<div class=\"app\">\r\n  <aside class=\"side\">\r\n    <div class=\"brand\">Gestor de Tráfego</div>\r\n    <nav class=\"nav\" aria-label=\"Principal\">\r\n      <a href=\"#/criativos\" data-nav=\"criativos\">Criativos</a>\r\n      <a href=\"#/cadastro\" data-nav=\"cadastro\">Cadastro</a>\r\n      <a href=\"#/lancamento\" data-nav=\"lancamento\">Lançamento</a>\r\n    </nav>\r\n  </aside>\r\n  <main class=\"main\"><div class=\"wrap\" id=\"view\"></div></main>\r\n</div>\r\n<div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\r\n<script type=\"module\">\r\nimport * as Calc from \"/shared/calc.js\";\r\n\r\nconst $ = (s, r = document) => r.querySelector(s);\r\nconst $$ = (s, r = document) => Array.from(r.querySelectorAll(s));\r\nconst esc = (s) => String(s ?? \"\").replace(/[&<>\"']/g, (c) => ({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\r\nconst view = () => $(\"#view\");\r\nconst toast = (m) => { const t = $(\"#toast\"); t.textContent = m; t.classList.add(\"on\"); clearTimeout(t._h); t._h = setTimeout(() => t.classList.remove(\"on\"), 2600); };\r\nconst fDate = (s) => { const [y, m, d] = String(s).split(\"-\"); return `${d}/${m}/${y.slice(2)}`; };\r\nconst todayLocal = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,\"0\")}-${String(d.getDate()).padStart(2,\"0\")}`; };\r\n// Usa o módulo único de cálculo servido pelo servidor (ao-vivo + formato BR).\r\nconst fBRL = (cents) => Calc.formatBRL(cents);\r\n\r\nconst FORMAT = { video: \"Vídeo\", image: \"Imagem\", carousel: \"Carrossel\" };\r\nconst STATUS = { ativo: \"Ativo\", escalando: \"Escalando\", pausado: \"Pausado\", encerrado: \"Encerrado\" };\r\n\r\nfunction chipFor(h) {\r\n  const map = { \"Saudável\": \"ok\", \"Atenção\": \"warn\", \"Escalando\": \"good\", \"Pausado\": \"bad\", \"Encerrado\": \"bad\", \"Sem dados\": \"wait\" };\r\n  return `<span class=\"chip ${map[h.statusDisplay] ?? \"wait\"}\">${esc(h.statusDisplay)}</span>`;\r\n}\r\nfunction rulerFor(h) {\r\n  const pos = { vermelho: 12, amarelo: 37, azul: 62, verde: 87 };\r\n  if (h.ruler === \"cinza\") return `<span class=\"ruler off\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i></span>`;\r\n  return `<span class=\"ruler\" role=\"img\" aria-label=\"Saúde ${esc(h.statusDisplay)}\"><i></i><i></i><i></i><i></i><b style=\"left:${pos[h.ruler] ?? 62}%\"></b></span>`;\r\n}\r\nconst profitClass = (cents) => cents == null ? \"\" : cents >= 0 ? \"good\" : \"bad\";\r\nasync function api(path, opts) {\r\n  const res = await fetch(path, opts);\r\n  const body = await res.json().catch(() => ({}));\r\n  if (!res.ok) { const e = new Error(body.error || \"erro\"); e.status = res.status; e.body = body; throw e; }\r\n  return body;\r\n}\r\n\r\n// ---------- Biblioteca ----------\r\nconst L = { q: \"\", status: \"all\", sort: \"recent\" };\r\nasync function pageLibrary() {\r\n  view().innerHTML = `\r\n  <div class=\"ph\"><div><h1>Criativos</h1><p class=\"sub\" id=\"lib-sub\">Biblioteca mínima — T2</p></div><a class=\"btn\" href=\"#/cadastro\">+ Cadastrar criativo</a></div>\r\n  <div class=\"fb\">\r\n    <label class=\"ctl search\"><input id=\"lib-q\" placeholder=\"Buscar por nome ou produto\" value=\"${esc(L.q)}\" aria-label=\"Buscar criativo\"></label>\r\n    <label class=\"ctl\">Status <select id=\"lib-status\"><option value=\"all\">Todos</option>${Object.entries(STATUS).map(([k,v]) => `<option value=\"${k}\">${v}</option>`).join(\"\")}</select></label>\r\n    <label class=\"ctl\">Ordenar <select id=\"lib-sort\"><option value=\"recent\">Mais recentes</option><option value=\"name\">Nome A–Z</option><option value=\"profit\">Maior lucro</option></select></label>\r\n  </div>\r\n  <section class=\"panel\"><div class=\"panel-b\" id=\"lib-body\">Carregando…</div></section>`;\r\n  $(\"#lib-status\").value = L.status; $(\"#lib-sort\").value = L.sort;\r\n  $(\"#lib-q\").addEventListener(\"input\", (e) => { L.q = e.target.value; libBody(); });\r\n  $(\"#lib-status\").addEventListener(\"change\", (e) => { L.status = e.target.value; libBody(); });\r\n  $(\"#lib-sort\").addEventListener(\"change\", (e) => { L.sort = e.target.value; libBody(); });\r\n  $(\"#lib-body\").addEventListener(\"click\", (e) => { const tr = e.target.closest(\"tr[data-id]\"); if (tr) location.hash = \"#/criativo/\" + tr.dataset.id; });\r\n  await libBody();\r\n}\r\nasync function libBody() {\r\n  const box = $(\"#lib-body\");\r\n  try {\r\n    const qs = new URLSearchParams();\r\n    if (L.q.trim()) qs.set(\"q\", L.q.trim());\r\n    if (L.status !== \"all\") qs.set(\"status\", L.status);\r\n    const { data } = await api(\"/api/creatives?\" + qs.toString());\r\n    let rows = [...data];\r\n    if (L.sort === \"name\") rows.sort((a, b) => a.name.localeCompare(b.name, \"pt-BR\"));\r\n    else if (L.sort === \"profit\") rows.sort((a, b) => (b.totals.profit_cents ?? -Infinity) - (a.totals.profit_cents ?? -Infinity));\r\n    else rows.sort((a, b) => b.start_date.localeCompare(a.start_date) || b.id - a.id);\r\n    $(\"#lib-sub\").textContent = `${rows.length} criativo(s) na biblioteca`;\r\n    if (!rows.length) { box.innerHTML = `<div class=\"empty\"><strong>Nenhum criativo encontrado</strong><span>Tente outra busca ou cadastre um novo.</span><a class=\"btn\" href=\"#/cadastro\">Cadastrar criativo</a></div>`; return; }\r\n    box.innerHTML = `<div style=\"overflow:auto\"><table class=\"tbl\"><thead><tr><th>Criativo</th><th>Status</th><th>Início</th><th class=\"num\">Investimento</th><th class=\"num\">Lucro</th><th>Saúde do dia</th><th>Motivo</th></tr></thead><tbody>${rows.map((c) => {\r\n      const pc = profitClass(c.totals.profit_cents);\r\n      return `<tr class=\"click\" data-id=\"${c.id}\"><td><div class=\"nm\">${esc(c.name)}</div><div class=\"sub\">${esc(c.product || \"—\")} · ${FORMAT[c.format] ?? c.format}</div></td><td>${chipFor(c.health)}</td><td>${fDate(c.start_date)}</td><td class=\"num\">${fBRL(c.totals.investment_cents)}</td><td class=\"num prof ${pc}\">${fBRL(c.totals.profit_cents)}</td><td>${rulerFor(c.health)}</td><td class=\"mut\">${esc(c.health.motivo ?? \"—\")}</td></tr>`;\r\n    }).join(\"\")}</tbody></table></div>`;\r\n  } catch { box.innerHTML = `<div class=\"empty\"><strong>Não foi possível carregar</strong></div>`; }\r\n}\r\n\r\n// ---------- Cadastro (T2 único + T3 em lote) ----------\r\n// produto/formato/data mantidos após cada cadastro para encadear o próximo.\r\nconst R = { mode: \"single\", name: \"\", bulk: \"\", product: \"\", format: \"video\", start: todayLocal(), status: \"ativo\", url: \"\", notes: \"\" };\r\nconst bulkNames = () => R.bulk.split(\"\\n\").map((s) => s.trim()).filter(Boolean);\r\nasync function pageRegister() {\r\n  let products = [];\r\n  let existing = [];\r\n  try { const { data } = await api(\"/api/creatives\"); products = [...new Set(data.map((c) => c.product).filter(Boolean))].sort((a,b)=>a.localeCompare(b,\"pt-BR\")); existing = data.map((c) => ({ name: c.name, status: c.status })); } catch {}\r\n  const bulk = R.mode === \"bulk\";\r\n  const isFuture = R.start > todayLocal();\r\n  view().innerHTML = `\r\n  <div class=\"ph\"><div><h1>Cadastro</h1><p class=\"sub\">Registre os criativos novos. Os números do dia entram depois, no lançamento.</p></div></div>\r\n  <div class=\"cols\">\r\n  <section class=\"panel\"><div class=\"panel-b\">\r\n    <div class=\"seg\" role=\"group\" aria-label=\"Modo de cadastro\"><button type=\"button\" data-mode=\"single\" aria-pressed=\"${!bulk}\">Um criativo</button><button type=\"button\" data-mode=\"bulk\" aria-pressed=\"${bulk}\">Vários de uma vez</button></div>\r\n    <div style=\"height:14px\"></div>\r\n    ${bulk\r\n      ? `<div class=\"fld\"><label for=\"r-bulk\">Nomes dos criativos (um por linha)</label><textarea class=\"in\" id=\"r-bulk\" rows=\"6\" placeholder=\"Depoimento cozinha 03&#10;UGC achadinho 04\">${esc(R.bulk)}</textarea><div class=\"bulkprev\" id=\"r-prev\" aria-live=\"polite\"></div><div class=\"err-msg\" id=\"r-err\" hidden></div></div>`\r\n      : `<div class=\"fld\"><label for=\"r-name\">Nome do criativo</label><input class=\"in\" id=\"r-name\" value=\"${esc(R.name)}\" placeholder=\"Ex.: Depoimento cozinha 03\" autocomplete=\"off\"><div class=\"err-msg\" id=\"r-err\" hidden></div></div>`}\r\n    <div class=\"fld\"><label for=\"r-product\">Produto ou oferta</label><input class=\"in\" id=\"r-product\" list=\"r-products\" value=\"${esc(R.product)}\" placeholder=\"Ex.: Mini processador\" autocomplete=\"off\"><datalist id=\"r-products\">${products.map((p)=>`<option value=\"${esc(p)}\">`).join(\"\")}</datalist><span class=\"hint\">Mantido após cadastrar para encadear o próximo.</span></div>\r\n    <div class=\"fld\"><span class=\"l\" style=\"font-weight:700\">Formato</span><div class=\"seg\" role=\"group\" aria-label=\"Formato\">${Object.entries(FORMAT).map(([k,v])=>`<button type=\"button\" data-format=\"${k}\" aria-pressed=\"${R.format===k}\">${v}</button>`).join(\"\")}</div></div>\r\n    <div class=\"two\">\r\n      <div class=\"fld\"><label for=\"r-start\">Data de início</label><input type=\"date\" class=\"in\" id=\"r-start\" value=\"${esc(R.start)}\"><span class=\"hint\">Mantida após cadastrar.</span></div>\r\n      <div class=\"fld\"><label for=\"r-status\">Status inicial</label><select class=\"in\" id=\"r-status\">${Object.entries(STATUS).map(([k,v])=>`<option value=\"${k}\">${v}</option>`).join(\"\")}</select></div>\r\n    </div>\r\n    ${isFuture ? `<p class=\"hint\" id=\"r-pre\">Pré-cadastro: começa em ${fDate(R.start)} — não conta Dia 1 nem dispara Sinal até ter movimento.</p>` : ``}\r\n    ${bulk ? `` : `\r\n    <div class=\"fld\"><label for=\"r-url\">Link do Criativo (opcional)</label><input class=\"in\" id=\"r-url\" type=\"url\" value=\"${esc(R.url)}\" placeholder=\"Pasta do Drive ou link do Criativo\"></div>\r\n    <div class=\"fld\"><label for=\"r-notes\">Observações (opcional)</label><textarea class=\"in\" id=\"r-notes\" placeholder=\"Gancho, ângulo, público…\">${esc(R.notes)}</textarea></div>`}\r\n    <div class=\"actions\"><button class=\"btn\" id=\"r-save\" type=\"button\"><span id=\"r-save-l\">Cadastrar</span></button><button class=\"btn ghost\" id=\"r-save-go\" type=\"button\">Cadastrar e lançar dados</button></div>\r\n  </div></section>\r\n  <section class=\"panel\"><div class=\"panel-b\"><strong>Últimos cadastrados</strong></div><ul class=\"recent\" id=\"r-recent\"><li class=\"mut\">Carregando…</li></ul></section>\r\n  </div>`;\r\n  $(\"#r-status\").value = R.status;\r\n  const errEl = () => $(\"#r-err\");\r\n  const showErr = (m, sel) => { const e = errEl(); e.textContent = m; e.hidden = false; const i = sel ? $(sel) : null; if (i) { i.classList.add(\"err\"); i.focus(); } };\r\n  const clearErr = () => { const e = errEl(); if (e) e.hidden = true; $$(\".in.err\").forEach((i)=>i.classList.remove(\"err\")); };\r\n  const paintPreview = () => {\r\n    const box = $(\"#r-prev\");\r\n    if (!box) { const l = $(\"#r-save-l\"); if (l) l.textContent = \"Cadastrar\"; return; }\r\n    const names = bulkNames();\r\n    const taken = new Set(existing.filter((c) => c.status !== \"encerrado\").map((c) => String(c.name).toLowerCase()));\r\n    const seen = new Set();\r\n    box.innerHTML = names.map((n) => {\r\n      const k = n.toLowerCase();\r\n      const dup = taken.has(k) || seen.has(k);\r\n      seen.add(k);\r\n      return `<span class=\"${dup ? \"dup\" : \"\"}\">${esc(n)}</span>`;\r\n    }).join(\"\");\r\n    $(\"#r-save-l\").textContent = names.length > 1 ? `Cadastrar ${names.length} criativos` : \"Cadastrar\";\r\n  };\r\n  $$(\"[data-mode]\").forEach((b) => b.addEventListener(\"click\", () => { R.mode = b.dataset.mode; pageRegister(); }));\r\n  const nameInput = $(\"#r-name\");\r\n  if (nameInput) nameInput.addEventListener(\"input\", (e) => { R.name = e.target.value; clearErr(); });\r\n  const bulkInput = $(\"#r-bulk\");\r\n  if (bulkInput) bulkInput.addEventListener(\"input\", (e) => { R.bulk = e.target.value; clearErr(); paintPreview(); });\r\n  $(\"#r-product\").addEventListener(\"input\", (e) => { R.product = e.target.value; });\r\n  $(\"#r-start\").addEventListener(\"change\", (e) => { R.start = e.target.value || todayLocal(); pageRegister(); });\r\n  $(\"#r-status\").addEventListener(\"change\", (e) => { R.status = e.target.value; });\r\n  const urlInput = $(\"#r-url\");\r\n  if (urlInput) urlInput.addEventListener(\"input\", (e) => { R.url = e.target.value; });\r\n  const notesInput = $(\"#r-notes\");\r\n  if (notesInput) notesInput.addEventListener(\"input\", (e) => { R.notes = e.target.value; });\r\n  $$(\"[data-format]\").forEach((b) => b.addEventListener(\"click\", () => { R.format = b.dataset.format; $$(\"[data-format]\").forEach((x)=>x.setAttribute(\"aria-pressed\", x===b)); }));\r\n  $(\"#r-save\").addEventListener(\"click\", () => submitRegister(false, showErr));\r\n  $(\"#r-save-go\").addEventListener(\"click\", () => submitRegister(true, showErr));\r\n  paintPreview();\r\n  await paintRecent();\r\n}\r\nasync function paintRecent() {\r\n  try {\r\n    const { data } = await api(\"/api/creatives\");\r\n    const last = [...data].sort((a,b)=>b.id-a.id).slice(0,6);\r\n    $(\"#r-recent\").innerHTML = last.length ? last.map((c)=>`<li><div><a href=\"#/criativo/${c.id}\">${esc(c.name)}</a><div class=\"sub\">${esc(c.product||\"—\")} · ${FORMAT[c.format]} · ${fDate(c.start_date)}</div></div>${chipFor(c.health)}</li>`).join(\"\") : `<li class=\"mut\">Nenhum criativo ainda.</li>`;\r\n  } catch { const el = $(\"#r-recent\"); if (el) el.innerHTML = `<li class=\"mut\">—</li>`; }\r\n}\r\nasync function submitRegister(goDaily, err) {\r\n  if (R.mode === \"bulk\") {\r\n    const names = bulkNames();\r\n    if (!names.length) { err(\"Digite pelo menos um nome, um por linha.\", \"#r-bulk\"); return; }\r\n    try {\r\n      const { data } = await api(\"/api/creatives/bulk\", { method: \"POST\", headers: {\"content-type\":\"application/json\"}, body: JSON.stringify({ names, product: R.product.trim(), format: R.format, start_date: R.start, status: R.status }) });\r\n      // Mantém produto/formato/data para encadear; limpa só a lista.\r\n      R.bulk = \"\";\r\n      toast(data.length === 1 ? `Criativo cadastrado: ${data[0].name}` : `${data.length} criativos cadastrados`);\r\n      if (goDaily) { location.hash = \"#/lancamento\"; } else { pageRegister(); const f = $(\"#r-bulk\"); if (f) f.focus(); }\r\n    } catch (e) {\r\n      const warns = e.body?.warnings ?? [];\r\n      if (e.body?.error === \"nome_duplicado\") err(warns[0] || \"Há nomes repetidos ou já cadastrados (em vermelho).\", \"#r-bulk\");\r\n      else err(\"Não foi possível cadastrar. Confira os campos.\", \"#r-bulk\");\r\n    }\r\n    return;\r\n  }\r\n  const payload = { name: R.name.trim(), product: R.product.trim(), format: R.format, start_date: R.start, status: R.status, url: R.url.trim(), notes: R.notes };\r\n  if (!payload.name) { err(\"Informe o nome do criativo.\", \"#r-name\"); return; }\r\n  try {\r\n    const { data } = await api(\"/api/creatives\", { method: \"POST\", headers: {\"content-type\":\"application/json\"}, body: JSON.stringify(payload) });\r\n    // Mantém produto/formato/data para encadear; limpa só nome/link/observações.\r\n    R.name = \"\"; R.url = \"\"; R.notes = \"\";\r\n    toast(`Criativo cadastrado: ${data.name}`);\r\n    if (goDaily) { location.hash = \"#/lancamento\"; } else { pageRegister(); const f = $(\"#r-name\"); if (f) f.focus(); }\r\n  } catch (e) {\r\n    const warns = e.body?.warnings ?? [];\r\n    if (e.body?.error === \"nome_duplicado\") err(warns[0] || \"Já existe um criativo com esse nome.\", \"#r-name\");\r\n    else err(\"Não foi possível cadastrar. Confira os campos.\", \"#r-name\");\r\n  }\r\n}\r\n\r\n// ---------- Detalhe mínimo (réplica-da-planilha chega no T4) ----------\r\nasync function pageDetail(id) {\r\n  try {\r\n    const { data: c } = await api(\"/api/creatives/\" + id);\r\n    const pc = profitClass(c.totals.profit_cents);\r\n    view().innerHTML = `\r\n    <a href=\"#/criativos\" style=\"color:var(--muted);text-decoration:none\">← Criativos</a>\r\n    <div class=\"ph\"><div><h1>${esc(c.name)}</h1><p class=\"sub\">${esc(c.product||\"—\")} · ${FORMAT[c.format]} · início em ${fDate(c.start_date)}</p></div><div>${chipFor(c.health)}</div></div>\r\n    <section class=\"panel\"><div class=\"panel-b\" style=\"display:flex;gap:24px;flex-wrap:wrap;align-items:center\">${rulerFor(c.health)}<span><strong class=\"prof ${pc}\">${fBRL(c.totals.profit_cents)}</strong> <span class=\"mut\">lucro · ${fBRL(c.totals.investment_cents)} investidos · ${c.totals.sales} vendas</span></span><span class=\"mut\">${esc(c.health.motivo ?? (c.health.dia1 ? \"—\" : \"Pré-cadastro: sem Dia 1, sem Sinal até ter movimento.\"))}</span></div></section>\r\n    <section class=\"panel\"><div class=\"panel-b\"><strong>Lançamentos diários</strong><p class=\"sub\">A planilha editável (TOTAL, filtro por mês, adicionar dia) chega no T4.</p><div class=\"actions\"><a class=\"btn ghost\" href=\"#/lancamento\">Ir para lançamento</a></div></div></section>`;\r\n  } catch { location.hash = \"#/criativos\"; }\r\n}\r\n// ---------- Lançamento diário em lote (T3) ----------\n// Um dia, todos os Ativos numa tabela só. Tudo recalcula ao digitar via Calc.\nconst DY = { date: todayLocal() };\nconst fmtInputCents = (cents) => cents == null ? \"\" : (cents / 100).toLocaleString(\"pt-BR\", { minimumFractionDigits: 2, maximumFractionDigits: 2 });\nfunction pageDaily() {\n  view().innerHTML = `\n  <div class=\"ph\"><div><h1>Lançamento diário</h1><p class=\"sub\">Lance o dia de todos os Ativos numa tabela só.</p></div><a class=\"btn ghost\" href=\"#/cadastro\">Cadastrar criativo</a></div>\n  <div class=\"daybar\">\n    <button class=\"btn ghost sm\" id=\"dy-prev\" type=\"button\" aria-label=\"Dia anterior\">←</button>\n    <input type=\"date\" class=\"in sm\" id=\"dy-date\" style=\"width:auto\" aria-label=\"Data do lançamento\">\n    <button class=\"btn ghost sm\" id=\"dy-next\" type=\"button\" aria-label=\"Próximo dia\">→</button>\n    <button class=\"btn ghost sm\" id=\"dy-today\" type=\"button\">Hoje</button>\n    <span class=\"long\" id=\"dy-long\"></span>\n  </div>\n  <section class=\"panel\"><div class=\"scroll\" id=\"dy-body\"><div class=\"panel-b mut\">Carregando…</div></div>\n    <div class=\"warnbox\" id=\"dy-warn\" hidden></div>\n    <div class=\"savebar\"><span id=\"dy-count\" class=\"mut\"></span><button class=\"btn\" id=\"dy-save\" type=\"button\">Salvar lançamentos</button></div></section>`;\n  const go = (d) => { if (!d || d > todayLocal()) return; DY.date = d; renderDay(); };\r\n  $(\"#dy-date\").max = todayLocal();\n  $(\"#dy-prev\").addEventListener(\"click\", () => {\n    const [y, m, d] = DY.date.split(\"-\").map(Number);\n    const dt = new Date(Date.UTC(y, m - 1, d - 1));\n    go(dt.toISOString().slice(0, 10));\n  });\n  $(\"#dy-next\").addEventListener(\"click\", () => {\n    const [y, m, d] = DY.date.split(\"-\").map(Number);\n    const dt = new Date(Date.UTC(y, m - 1, d + 1));\n    const iso = dt.toISOString().slice(0, 10);\n    if (iso <= todayLocal()) go(iso);\n  });\n  $(\"#dy-today\").addEventListener(\"click\", () => go(todayLocal()));\n  $(\"#dy-date\").addEventListener(\"change\", (e) => go(e.target.value));\n  $(\"#dy-save\").addEventListener(\"click\", saveDay);\n  const body = $(\"#dy-body\");\n  body.addEventListener(\"input\", (ev) => { const tr = ev.target.closest(\"tr[data-cid]\"); if (tr) { paintDayRow(tr); countDay(); } });\n  body.addEventListener(\"keydown\", (ev) => {\n    if (ev.key !== \"Enter\" || !ev.target.matches(\"input[data-f]\")) return;\n    ev.preventDefault();\n    const nxt = ev.target.closest(\"tr\").nextElementSibling;\n    const t = nxt ? nxt.querySelector(`input[data-f=\"${ev.target.dataset.f}\"]`) : null;\n    if (t) { t.focus(); t.select(); } else $(\"#dy-save\").focus();\n  });\n  renderDay();\n}\nasync function renderDay() {\n  const date = DY.date;\n  $(\"#dy-date\").value = date;\n  $(\"#dy-next\").disabled = date >= todayLocal();\n  const [y, m, d] = date.split(\"-\");\n  $(\"#dy-long\").textContent = `${d}/${m}/${y.slice(2)}`;\n  const box = $(\"#dy-body\");\n  try {\n    const { data } = await api(\"/api/entries?date=\" + date);\n    if (!data.length) {\n      box.innerHTML = `<div class=\"empty\"><strong>Nenhum criativo ativo</strong><span>Cadastre um criativo ou mude o status para Ativo/Escalando.</span><a class=\"btn\" href=\"#/cadastro\">Cadastrar criativo</a></div>`;\n      $(\"#dy-save\").disabled = true; $(\"#dy-count\").textContent = \"\";\n      return;\n    }\n    const cell = (f, val, mode, ph) => `<td><input class=\"ci\" data-f=\"${f}\" inputmode=\"${mode}\" value=\"${esc(val)}\" placeholder=\"${esc(ph)}\"></td>`;\n    box.innerHTML = `<table class=\"tbl daytbl\"><thead><tr><th>Criativo</th><th class=\"num\">Invest. (R$)</th><th class=\"num\">Vendas</th><th class=\"num\">Fatur. (R$)</th><th class=\"num\">Cliques Meta</th><th class=\"num\">Cliques Shopee</th><th class=\"num\">Custo</th><th class=\"num\">Lucro</th><th class=\"num\">CPC Meta</th><th class=\"num\">CPC Shopee</th><th>Saúde</th></tr></thead><tbody>${data.map((r) => {\n      const e = r.entry;\n      return `<tr data-cid=\"${r.creative.id}\" data-tax=\"${r.tax_rate}\" data-dia1=\"${esc(r.dia1 ?? \"\")}\"><td><div class=\"nm\">${esc(r.creative.name)}</div><div class=\"sub\">${esc(r.creative.product || \"—\")}</div></td>`\n        + cell(\"invest\", e ? fmtInputCents(e.investment_cents) : \"\", \"decimal\", \"0,00\")\n        + cell(\"sales\", e ? String(e.sales) : \"\", \"numeric\", \"0\")\n        + cell(\"rev\", e && e.revenue_cents != null ? fmtInputCents(e.revenue_cents) : \"\", \"decimal\", \"pendente\")\n        + cell(\"clM\", e ? String(e.clicks_meta) : \"\", \"numeric\", \"0\")\n        + cell(\"clS\", e ? String(e.clicks_shopee) : \"\", \"numeric\", \"0\")\n        + `<td class=\"calc\" data-c=\"cost\">—</td><td class=\"calc\" data-c=\"profit\">—</td><td class=\"calc\" data-c=\"cpcM\">—</td><td class=\"calc\" data-c=\"cpcS\">—</td><td class=\"mut\" data-c=\"health\">—</td></tr>`;\n    }).join(\"\")}</tbody></table>`;\n    $$(\"#dy-body tr[data-cid]\").forEach(paintDayRow);\n    countDay();\n    const w = $(\"#dy-warn\"); if (w) w.hidden = true;\n  } catch {\n    box.innerHTML = `<div class=\"empty\"><strong>Não foi possível carregar o dia</strong></div>`;\n  }\n}\nfunction paintDayRow(tr) {\n  const tax = Number(tr.dataset.tax || 0.1386);\n  const date = DY.date;\n  const dia1 = tr.dataset.dia1 || null;\n  const inv = Calc.parseMoedaParaCentavos($('[data-f=\"invest\"]', tr).value);\n  const rev = Calc.parseMoedaParaCentavos($('[data-f=\"rev\"]', tr).value);\n  const sales = Calc.parseInteiro($('[data-f=\"sales\"]', tr).value);\n  const clM = Calc.parseInteiro($('[data-f=\"clM\"]', tr).value);\n  const clS = Calc.parseInteiro($('[data-f=\"clS\"]', tr).value);\n  const invC = inv == null ? 0 : inv;\n  const salesN = sales == null ? 0 : sales;\n  const clMN = clM == null ? 0 : clM;\n  const clSN = clS == null ? 0 : clS;\n  const bad = [inv, sales, clM, clS].some((v) => typeof v === \"number\" && Number.isNaN(v)) || (rev != null && Number.isNaN(rev));\r\n  // Módulo único de cálculo (spec #6): custo/lucro/CPCs/pendente vêm do Calc.\r\n  const row = bad ? null : Calc.calcRow({ date, investment_cents: invC, sales: salesN, revenue_cents: rev, clicks_meta: clMN, clicks_shopee: clSN, tax_rate: tax });\r\n  const cost = row ? row.cost_cents : null;\r\n  const isPending = row ? row.is_pending : false;\r\n  const profit = row ? row.profit_cents : null;\r\n  const cpcM = row ? row.cpc_meta_cents : null;\r\n  const cpcS = row ? row.cpc_shopee_cents : null;\n  $('[data-c=\"cost\"]', tr).textContent = Calc.formatBRL(cost);\n  const pEl = $('[data-c=\"profit\"]', tr);\n  pEl.textContent = isPending ? \"pendente\" : Calc.formatBRL(profit);\n  pEl.className = \"calc\" + (profit == null || isPending ? \"\" : profit >= 0 ? \" prof good\" : \" prof bad\");\n  $('[data-c=\"cpcM\"]', tr).textContent = Calc.formatCPC(cpcM);\n  $('[data-c=\"cpcS\"]', tr).textContent = Calc.formatCPC(cpcS);\n  const hEl = $('[data-c=\"health\"]', tr);\n  if (bad || (invC === 0 && salesN === 0 && clMN === 0 && clSN === 0 && rev == null)) { hEl.textContent = \"—\"; return; }\n  try {\n    const isDia1 = !dia1 || date <= dia1;\n    const sig = Calc.evaluateDay({ date, investment_cents: invC, sales: salesN, revenue_cents: rev, clicks_meta: clMN, clicks_shopee: clSN, tax_rate: tax }, isDia1);\n    hEl.textContent = sig.saude === \"atencao\" ? `Atenção · ${sig.motivo ?? \"\"}` : (sig.motivo ?? \"Saudável\");\n  } catch { hEl.textContent = \"—\"; }\n}\nconst rowFilled = (tr) => [\"invest\", \"sales\", \"rev\", \"clM\", \"clS\"].some((f) => $('[data-f=\"' + f + '\"]', tr).value.trim() !== \"\");\nfunction countDay() {\n  const rows = $$(\"#dy-body tr[data-cid]\");\n  if (!rows.length) return;\n  const n = rows.filter(rowFilled).length;\n  $(\"#dy-count\").textContent = `${n} de ${rows.length} preenchidos`;\n  $(\"#dy-save\").disabled = n === 0;\n}\nasync function saveDay() {\n  const rows = $$(\"#dy-body tr[data-cid]\");\n  const entries = [];\n  $$(\"#dy-body .ci.bad\").forEach((i) => i.classList.remove(\"bad\"));\n  for (const tr of rows) {\n    if (!rowFilled(tr)) continue;\n    const cid = Number(tr.dataset.cid);\n    const inv = Calc.parseMoedaParaCentavos($('[data-f=\"invest\"]', tr).value);\n    const rev = Calc.parseMoedaParaCentavos($('[data-f=\"rev\"]', tr).value);\n    const sales = Calc.parseInteiro($('[data-f=\"sales\"]', tr).value);\n    const clM = Calc.parseInteiro($('[data-f=\"clM\"]', tr).value);\n    const clS = Calc.parseInteiro($('[data-f=\"clS\"]', tr).value);\n    const name = $(\".nm\", tr).textContent;\n    const mark = (f) => $('[data-f=\"' + f + '\"]', tr).classList.add(\"bad\");\n    let bad = false;\n    for (const [f, v] of [[\"invest\", inv], [\"sales\", sales], [\"rev\", rev], [\"clM\", clM], [\"clS\", clS]]) {\n      if (typeof v === \"number\" && Number.isNaN(v)) { mark(f); bad = true; }\n      if (typeof v === \"number\" && v != null && v < 0) { mark(f); bad = true; }\n    }\n    for (const [f, v] of [[\"sales\", sales], [\"clM\", clM], [\"clS\", clS]]) {\n      if (typeof v === \"number\" && v != null && !Number.isInteger(v)) { mark(f); bad = true; }\n    }\n    if (bad) { toast(`Confira os números de ${name}.`); return; }\n    entries.push({ creative_id: cid, investment_cents: inv ?? 0, sales: sales ?? 0, revenue_cents: rev, clicks_meta: clM ?? 0, clicks_shopee: clS ?? 0 });\n  }\n  if (!entries.length) { toast(\"Preencha ao menos um criativo.\"); return; }\n  try {\n    const { warnings } = await api(\"/api/entries/bulk\", { method: \"POST\", headers: {\"content-type\":\"application/json\"}, body: JSON.stringify({ date: DY.date, entries }) });\n    const w = $(\"#dy-warn\");\n    if (warnings?.length) { w.textContent = warnings.join(\" \"); w.hidden = false; }\n    else if (w) w.hidden = true;\n    toast(`${entries.length} ${entries.length === 1 ? \"lançamento salvo\" : \"lançamentos salvos\"} em ${fDate(DY.date)}`);\n    renderDay();\n  } catch (e) {\n    toast(e.body?.error === \"encerrado_sem_lancamento\" ? \"Criativo encerrado não recebe lançamentos.\" : \"Não foi possível salvar. Confira os números (nada negativo; vendas/cliques inteiros).\");\n  }\n}\n\nfunction router() {\r\n  $$(\".nav a\").forEach((a) => a.removeAttribute(\"aria-current\"));\r\n  const h = location.hash || \"#/criativos\";\r\n  if (h.startsWith(\"#/cadastro\")) { $('[data-nav=\"cadastro\"]').setAttribute(\"aria-current\",\"page\"); pageRegister(); }\r\n  else if (h.startsWith(\"#/criativo/\")) { $('[data-nav=\"criativos\"]').setAttribute(\"aria-current\",\"page\"); pageDetail(h.split(\"/\")[2]); }\r\n  else if (h.startsWith(\"#/lancamento\")) { $('[data-nav=\"lancamento\"]').setAttribute(\"aria-current\",\"page\"); pageDaily(); }\r\n  else { $('[data-nav=\"criativos\"]').setAttribute(\"aria-current\",\"page\"); pageLibrary(); }\r\n}\r\nwindow.addEventListener(\"hashchange\", router);\r\nrouter();\r\n</script>\r\n</body>\r\n</html>\r\n";
export const APP_VERSION = "0.1.0";
